// HasOperation applies the HasEdge predicate on the "operation" edge.
func HasOperation() predicate.RelationshipOperationStep {
	return predicate.RelationshipOperationStep(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2O, true, OperationTable, OperationColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasOperationWith applies the HasEdge predicate on the "operation" edge with a given conditions (other predicates).
func HasOperationWith(preds ...predicate.RelationshipOperation) predicate.RelationshipOperationStep {
	return predicate.RelationshipOperationStep(func(s *sql.Selector) {
		step := newOperationStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RelationshipOperationStep) predicate.RelationshipOperationStep {
	return predicate.RelationshipOperationStep(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RelationshipOperationStep) predicate.RelationshipOperationStep {
	return predicate.RelationshipOperationStep(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RelationshipOperationStep) predicate.RelationshipOperationStep {
	return predicate.RelationshipOperationStep(sql.NotPredicates(p))
}
